def A(text, ok, note): return {"text": text, "result": "PASS" if ok else "FAIL", "note": note}
def I(idx, typ, label, status, note, basic, spec, assertions, exec_note):
    p = sum(1 for a in assertions if a["result"] == "PASS")
    return {"index": idx, "type": typ, "label": label, "status": status,
            "status_flag": "\u2705" if (status == "COMPLETED" and basic + spec >= 75) else ("\u26a0\ufe0f" if status == "COMPLETED" else "\u274c"),
            "note": note, "basic": basic, "specialized": spec, "total": basic + spec,
            "assertions_passed": p, "assertions_total": len(assertions), "assertions": assertions,
            "executed": True, "execution_note": exec_note}

